from lib import *
S = SS('n1')
steps = [
    step("tree.go 里一个节点只有 8 个字段:path(这条边上的字符串)、indices(子节点首字节的合集)、wildChild、nType、priority、children、handlers、fullPath。nodeType 只有四种:static、root、param、catchAll。root 只是“整棵树的根”这个标记,不对应一种通配语法。", t=tl(S(1)), mark=lidx(S(1), 'static nodeType = iota', 'catchAll'), done=lidx(S(1), 'path      string', 'indices   string', 'children  []*node'), kv=KV([['nodeType', 'static / root / param / catchAll 四种'], ['indices', '所有静态子节点首字节拼成的字符串'], ['children', '注释写明:最多有 1 个 :param 风格的节点,放在数组最后']], ['nodeType'])),
    step("按 / → /users → /users/:id → /users/:id/posts → /users/new → /static/*filepath → /search → /src/a/b 的顺序注册 8 条 GET 路由后,树一共 12 个节点。根 \"/\" 的 indices=\"us\"(下面有 users 和 s 两条边);“s”再分出 \"tatic\"、\"earch\"、\"rc/a/b\";\"/users/\" 这一层的 wildChild=true,indices 里只有 \"n\"(静态的 new),:id 这个 param 节点不在 indices 里,而是排在 children 数组最后。", t=tl(S(2)), mark=lidx(S(2), '"/" [root', '"/" [static prio=3 indices="n" wildChild]', ':id" [param'), done=lidx(S(2), '"tatic"', '"earch"', '"rc/a/b"'), kv=KV([['8 条路由', '12 个节点'], ['"s" 之下', 'tatic / earch / rc/a/b,共用首字母 s'], ['wildChild', '"/users/" 这层为 true,:id 不进 indices']], ['8 条路由'])),
    step("只注册 /users/:id 时,树是一个 \"/users/\"(root,wildChild)带一个 \":id\"(param)子节点。*filepath 却用了两个节点:一个 path 为空的 catchAll 节点,下面再挂 \"/*filepath\"。/a/:x/b/:y/*rest 则是 param、静态、param、空节点、catchAll 逐层相接。", t=tl(S(3)), mark=lidx(S(3), '":id" [param prio=1 indices=""] handlers=1', '"/*filepath" [catchAll', '"/*rest" [catchAll'), done=lidx(S(3), '"/users/" [root', '"/static" [root', '"/a/" [root'), kv=KV([[':id', '1 个 param 节点'], ['*filepath', '2 个 catchAll 节点:空 path + "/*filepath"'], ['/a/:x/b/:y/*rest', '参数与静态段交替成树']], ['*filepath'])),
    step("同一棵树上的匹配结果:/users/new 命中静态节点(Params 为空);/users/42 命中 :id,FullPath 是 \"/users/:id\",Params=[{id 42}];/static/css/app.css 的 filepath 带着开头的斜杠 \"/css/app.css\";/static/ 的 filepath 是 \"/\";多个通配符 /a/1/b/2/c/d/e 取出 x=1、y=2、rest=\"/c/d/e\"。没注册 /users 本身时,/users/ 是 404;/static(少一个斜杠)被 301 重定向到 /static/。", t=tl(S(4)), mark=lidx(S(4), '/users/new', '/static/css/app.css', '/a/1/b/2/c/d/e'), done=lidx(S(4), '/users/42                    →'), kv=KV([['/users/new', '静态节点优先,Params 为空'], ['*filepath', '值以 / 开头'], ['/static', '301 到 /static/']], ['*filepath'])),
    step("规模:1000 条 /api/v1/resourceN/list 形式的静态路由共用前缀后只有 1100 个节点;同样 1000 条改成 /api/v1/resourceN/:id,节点数翻到 2100(每条路由多一个 param 节点)。4 个 HTTP 方法各注册 /x,会得到 4 棵独立的树,顺序是注册顺序 GET、POST、PUT、DELETE。", t=tl(S(5)), mark=lidx(S(5), '1100', '2100'), done=lidx(S(5), '[GET POST PUT DELETE]'), b=bars([['1000 条静态路由', 1100, '1100 个节点'], ['1000 条带 :id 的路由', 2100, '2100 个节点']], 2100, done=[0], mark=[1]), kv=KV([['静态 1000 条', '1100 个节点'], ['带 :id 的 1000 条', '2100 个节点'], ['方法', '每个 HTTP 方法一棵树']], ['带 :id 的 1000 条'])),
]
A = mkartn('n1', 1, 'Gin,路由树,radix tree,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测路由树的节点:源码里 node 结构体的 8 个字段和 4 种 nodeType;8 条路由注册后树只有 12 个节点,wildChild、indices 和 :id 的位置;*filepath 要用两个 catchAll 节点;参数怎么取出;1000 条静态路由 1100 个节点、带 :id 则 2100 个。',
    'Gin 的路由是一棵压缩前缀树,但“压缩”之后树到底长什么样?这篇在 Gin 源码副本里加了一个只读的打印函数,把 8 条路由注册后的真实节点逐个打出来,再对着 tree.go 里的字段和注释看每个字段是干什么的。',
    [('12', '8 条路由注册后树里的节点个数'), ('4 种', 'nodeType:static、root、param、catchAll'), ('1100 / 2100', '1000 条静态路由 / 1000 条带 :id 路由的节点数')],
    [('node 结构体:8 个字段、4 种类型', '<p>Gin 的路由树节点非常小:一条边上的字符串 <code>path</code>、子节点首字节拼成的 <code>indices</code>、是否带通配子节点的 <code>wildChild</code>、类型 <code>nType</code>、优先级 <code>priority</code>、<code>children</code>、<code>handlers</code> 和完整路由 <code>fullPath</code>。类型只有 static、root、param、catchAll 四种,root 不是一种通配语法,只是根节点的标记。</p><p><code>children</code> 的源码注释写着“最多一个 :param 风格的节点,放在数组最后”,下一节的树印证了这点。</p>'),
     ('8 条路由,12 个节点', '<p>“压缩前缀树”的压缩体现在:<code>/users</code>、<code>/users/:id</code>、<code>/users/new</code> 共用 <code>users</code> 这条边,<code>/static</code>、<code>/search</code>、<code>/src/a/b</code> 共用首字母 <code>s</code>。<code>indices</code> 只放静态子节点的首字节,所以 <code>:id</code> 不在 <code>"/users/"</code> 这层的 indices 里(那里只有 <code>n</code>),而是排在 children 数组的最后,<code>wildChild</code> 为真。</p><p>树里“长什么样”我只验证到这一层;匹配时先查 indices、再落到通配子节点的顺序,在后面讲优先级和 param 与 catchAll 的差别时再用实验验证。</p>'),
     (':id 和 *filepath 的结构', '<p>只有 <code>/users/:id</code> 时,树就是一个 <code>"/users/"</code> 带一个 <code>":id"</code>。<code>*filepath</code> 则占两个节点:一个 path 为空的 catchAll 节点和下面的 <code>"/*filepath"</code>。我只验证了树的形状,没有逐行去验证 <code>insertChild</code> 里每个分支的作用。</p>'),
     ('匹配出来的参数', '<p><code>c.FullPath()</code> 返回的是注册时的路由模板,<code>c.Params</code> 才是 URL 里取出的值。通配符 <code>*filepath</code> 的值总是以 <code>/</code> 开头,拼路径时别再多加一个斜杠。没有注册 <code>/users</code> 时,<code>/users/</code> 是 404;<code>/static</code> 因为后面有 <code>/static/*filepath</code>,被 301 重定向到 <code>/static/</code>。</p>'),
     ('规模与每方法一棵树', '<p>静态路由共用前缀,1000 条只要 1100 个节点;每条路由多一个参数就多一个 param 节点,2100 个。不同 HTTP 方法各自一棵树,所以同一个路径用 GET 和 POST 注册不会互相干扰,树也不会共享。</p>')],
    steps,
    [ENV_N_GIN + '。DumpTree 是我在 Gin v1.12.0 源码副本里新增的 zz_dump.go(只读遍历 Engine.trees,不改变任何行为),方便把内部节点打印出来;文中的行号是模块缓存里原文的行号;每种情形各一次',
     '没有验证:insertChild 里每个分支(如 catchAll 前一个字符必须是斜杠的检查)是否都由本文的例子覆盖;其他版本的 Gin 里节点结构是否一致(只看了 v1.12.0);路由数量更大(几万条)时的内存占用;Engine.maxParams / maxSections 等预分配字段的作用'],
    '路由树节点')
